package pbl6.ctsv.mghp.configuration;
import java.net.URI;import java.util.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.dao.DataAccessException;import org.springframework.transaction.TransactionException;import pbl6.ctsv.auth.AuthFailure;import pbl6.ctsv.foundation.api.FoundationAccess;
@RestControllerAdvice(assignableTypes=MghpController.class)
class ConfigurationErrors {
 @ExceptionHandler(ConfigFailure.class)ResponseEntity<?> known(ConfigFailure e,HttpServletRequest r){return error(e.status,e.code,e.field,r);}
 @ExceptionHandler(FoundationAccess.Failure.class)ResponseEntity<?> access(FoundationAccess.Failure e,HttpServletRequest r){return error(e.status(),e.code(),e.field(),r);}
 @ExceptionHandler(AuthFailure.class)ResponseEntity<?> auth(AuthFailure e,HttpServletRequest r){return error(e.status(),e.code(),"request",r);}
 @ExceptionHandler({DataAccessException.class,TransactionException.class})ResponseEntity<?> sql(RuntimeException e,HttpServletRequest r){boolean down=e instanceof TransactionException;for(Throwable t=e;t!=null;t=t.getCause())if(t instanceof java.sql.SQLException s){if(s.getErrorCode()==1205||s.getErrorCode()==1222||s.getSQLState()!=null&&s.getSQLState().startsWith("08"))down=true;if(s.getErrorCode()==2601||s.getErrorCode()==2627){if(s.getMessage().contains("uq_mghp_dot_xet"))return error(409,"ROUND_CODE_CONFLICT","code",r);if(s.getMessage().contains("uq_mghp_phien_ban_chinh_sach"))return error(409,"POLICY_VERSION_CONFLICT","version",r);return error(400,"VALIDATION_ERROR","code",r);}}return error(down?503:500,down?"DEPENDENCY_UNAVAILABLE":"INTERNAL_ERROR","request",r);}
 @ExceptionHandler(org.springframework.web.HttpRequestMethodNotSupportedException.class)ResponseEntity<?> method(Exception e,HttpServletRequest r){return error(405,"METHOD_NOT_ALLOWED","request",r);}
 @ExceptionHandler(Exception.class)ResponseEntity<?> other(Exception e,HttpServletRequest r){return error(500,"INTERNAL_ERROR","request",r);}
 private ResponseEntity<?> error(int status,String code,String field,HttpServletRequest r){var p=ProblemDetail.forStatusAndDetail(HttpStatus.valueOf(status),HttpStatus.valueOf(status).getReasonPhrase());p.setType(URI.create("about:blank"));p.setInstance(URI.create(r.getRequestURI()));p.setProperty("code",code);p.setProperty("traceId",UUID.randomUUID().toString());if(status==400)p.setProperty("errors",List.of(Map.of("field",field,"code",code,"message","Dữ liệu không hợp lệ")));return ResponseEntity.status(status).cacheControl(CacheControl.noStore()).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(p);}
}
